SELECT "SalariesFrance_13"."ROME" AS "ROME",   "SalariesFrance_13"."ROME_LIB" AS "ROME_LIB",   MIN("SalariesFrance_13"."CODGEO_PRINCIPAL") AS "min_CODGEO_PRINCIPAL_nk",   SUM("SalariesFrance_13"."EMPSAL_NP1") AS "sum_EMPSAL_NP1_ok" FROM "SalariesFrance_13" WHERE ("SalariesFrance_13"."REG_LIB" = 'BOURGOGNE-FRANCHE-COMTÉ') GROUP BY "SalariesFrance_13"."ROME",   "SalariesFrance_13"."ROME_LIB" HAVING (SUM("SalariesFrance_13"."EMPSAL_NP1") >= cast('0' as double));
